feed:
  {{ site.name }}
  {{ site.tagline }}


  {{ site_url }}/
  {{ updated }}

    {{ site.name }}
    {%- if site.email %}
    {{ site.email }}
    {%- endif %}

{%- for article in articles %}

    {{ article.title }}

    {{ site_url }}{{ article.url }}
    {{ article.date.isoformat() }}T00:00:00{{ site_tz }}
    {{ (article.updated or article.date).isoformat() }}T00:00:00{{ site_tz }}
    {%- for tag in article.tags %}

    {%- endfor %}
    {{ article.summary }}
    {{ article.html | e }}

{%- endfor %}
